function calculateCellValue(cellElement) {
    const value = cellElement.textContent.trim();

    if (!value || typeof value !== 'string') {
        return '';
    }

    // 1. Check for Formula Start
    if (value.startsWith('=')) {
        let formulaBody = value.substring(1).trim();
        let result;

        try {
            // Handle SUMA function first
            if (formulaBody.toUpperCase().startsWith("SUMA")) {
                const argsString = formulaBody.substring(4).trim(); // Skip "SUMA"
                result = calculateSum(argsString);
            } 
            // Handle basic arithmetic operations
            else if (/[a-zA-Z]/.test(formulaBody) && !isNaN(parseFloat(formulaBody))) {
                // Simple check to see if it looks like a formula involving cell references and operators
                result = evaluateFormulaString(formulaBody);
            } else {
                // If it's not a recognized formula, treat it as text/number input
                return value; 
            }

            if (result === null) {
                 return "Error"; // Generic error handling for failed calculation
            }
            return result.toString();

        } catch (e) {
            console.error("Formula evaluation error:", e);
            return "ERROR";
        }
    } else {
        // 2. Simple Data Input (Number or Text)
        if (!isNaN(parseFloat(value)) && isFinite(value)) {
            return parseFloat(value).toFixed(2).replace(/\.?0+$/, ''); // Format numbers cleanly
        }
        return value;
    }
}

