            const startCoords = getCellCoordinatesFromReference(startRef);
            if (!startCoords) continue;

            // Get coordinates from the end reference
            const endCoords = getCellCoordinatesFromReference(endRef);
            if (!endCoords) continue;

            // Iterate through rows and columns within the range
            for (let r = startCoords.row; r <= endCoords.row; r++) {
                for (let c = startCoords.col; c <= endCoords.col; c++) {
                    const cellElement = document.querySelector(`[data-col="${getColLetter(c)}"][data-row="${r}"]`);
                    if (cellElement) {
                        const value = calculateCellValue(cellElement); // Recursively calculate value
                        if (!isNaN(parseFloat(value)) && isFinite(value)) {
                            sumRange += parseFloat(value);
                        }
                    }
                }
            }
            total += sumRange;

        } else {
            // Discrete cell reference (e.g., A1)
            const coords = getCellCoordinatesFromReference(part);
            if (coords) {
                const cellElement = document.querySelector(`[data-col="${getColLetter(coords.col)}"][data-row="${coords.row}"]`);
                if (cellElement) {
                    const value = calculateCellValue(cellElement); // Recursively calculate value
                    if (!isNaN(parseFloat(value)) && isFinite(value)) {
                        total += parseFloat(value);
                    }
                }
            }
        }
    }

    return total;
}


