/**
 * Converts a cell reference string (e.g., "A1", "J20") into internal coordinates {col: 0, row: 0}.
 */
function getCellCoordinatesFromReference(ref) {
    if (!ref || typeof ref !== 'string') return null;

    // Extract column letters and row numbers
    const colLetters = ref.match(/[A-Z]+/g);
    const rowDigits = ref.match(/\d+/g);

    if (!colLetters || !rowDigits) return null;

    let colStr = colLetters[0];
    let rowNum = parseInt(rowDigits[0]);

    // Convert column letters (A, B, C...) to 0-indexed number (0, 1, 2...)
    let colIndex = 0;
    for (let i = 0; i < colStr.length; i++) {
        colIndex += (colStr.charCodeAt(i) - 'A'.charCodeAt(0) + 1) * Math.pow(26, colStr.length - 1 - i);
    }
    // Since we are using A=0, B=1... for simplicity in the grid structure:
    let finalColIndex = colStr.charCodeAt(0) - 'A'.charCodeAt(0);

    return { col: finalColIndex, row: rowNum };
}


/**
 * Converts a 0-indexed column number (0, 1, 2...) back to its letter (A, B, C...).
 */
function getColLetter(index) {
    if (index < 0 || index >= 26) return '';
    return String.fromCharCode('A'.charCodeAt(0) + index);
}

