        // Check if the current cell contains a formula and references the changed cell
        const formulaContent = cell.textContent.trim();
        if (formulaContent && formulaContent.startsWith('=')) {
            const formulaBody = formulaContent.substring(1);

            // Simple check: Does the formula string contain the reference of the changed cell?
            const targetRefRegex = new RegExp(`[A-Z]+${changedRow}:?[A-Z]*`, 'g'); 
            if (targetRefRegex.test(formulaBody)) {
                needsRecalculation = true;
                formulaFound = true;
            }
        }

        // If it's a formula and depends on the changed cell, recalculate it.
        if (formulaFound && needsRecalculation) {
             const newContent = calculateCellValue(cell);
             cell.textContent = newContent;
        }
    });
}


