    if (!target.classList.contains('cell')) return;

    // 1. Update the displayed value (and potentially calculate it if it's a formula)
    const newContent = calculateCellValue(target);
    target.textContent = newContent;

    // 2. Recalculate all dependent cells
    findAndRecalculateDependencies(target);
}
