function calculateFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return null; // Not a formula or invalid
    }

    // Remove the leading '=' sign for parsing
    let content = formula.substring(1).trim();

    // Regex to capture function name and arguments/ranges inside parentheses
    const match = content.match(/^([A-Z]+)\s*\((.*)\)$/i);

    if (!match) {
        return null; // Does not look like a recognized formula structure
    }

    const functionName = match[1].toUpperCase();
    let argumentsString = match[2];

    // Handle different argument separators (semicolon or comma)
    let argsArray;
    if (argumentsString.includes(';') && !argumentsString.includes(',')) {
        argsArray = argumentsString.split(';').map(s => s.trim());
    } else if (argumentsString.includes(',') && !argumentsString.includes(';')) {
        argsArray = argumentsString.split(',').map(s => s.trim());
    } else {
        // Fallback or complex case handling (assuming simple separation for now)
        argsArray = argumentsString.split(/[,;]/).map(s => s.trim()).filter(s => s.length > 0);
    }

    try {
        switch (functionName) {
            case 'SUMA':
                let sum = 0;
                for (const arg of argsArray) {
                    if (arg.includes(':')) {
                        // Range handling (e.g., A1:A3)
