### FUNCION: calculateFormula
```javascript
function calculateFormula(cellElement) {
    const formula = cellElement.dataset.formula;
    if (!formula) return null;

    try {
        // 1. Get all values from the grid to use in evaluation context
        const grid = document.getElementById('spreadsheet-grid');
        const cells = grid.querySelectorAll('.cell[data-row][data-col]');
        const values = {};

        cells.forEach(cell => {
            const row = cell.dataset.row;
            const col = cell.dataset.col;
            // Use the displayed text content as the current value for calculation
            values[`${col}${row}`] = parseFloat(cell.textContent) || 0;
        });

        // 2. Create a scope object for evaluation (e.g., { B1: 2, C1: 3 })
        let scope = {};
        for (const key in values) {
            scope[key] = values[key];
        }

        // 3. Evaluate the formula using the defined scope
        // Replace cell references like B1 with their actual numeric values from the scope
        let evaluatedFormula = formula;

        // Regex to find patterns like A1, B2, etc. (assuming standard column letters and row numbers)
        const cellRefRegex = /([A-Z]+[0-9]+)/g; 

        evaluatedFormula = evaluatedFormula.replace(cellRefRegex, (match) => {
            // Check if the matched reference exists in our scope
            if (scope.hasOwnProperty(match)) {
                return scope[match]; // Replace with the actual value
            }
            // If not found, treat it as 0 or handle error gracefully
            console.warn(`Undefined cell reference used in formula: ${match}`);
            return 0; 
        });

        // Use Function constructor for safe evaluation within scope context
        const result = new Function('scope', `return (${evaluatedFormula})(scope);`)(scope);

        if (isNaN(result) || !isFinite(result)) {
             return "Error"; // Handle calculation errors
        }

        // Return the calculated value, formatted as a string for display
        return String(parseFloat(result.toFixed(2))); 

    } catch (e) {
        console.error("Formula calculation error:", e);
        return ""; // Return empty string on critical failure
    }
}
```

