function setupEventListeners() {
    const grid = document.getElementById('spreadsheet-grid');
    if (!grid) return;

    // 1. Cell Selection and Interaction (Click/Focus)
    grid.addEventListener('click', function(e) {
        let target = e.target.closest('.cell');
        if (target && !target.classList.contains('selected')) {
            selectCell(target);
            showColorPicker(target, e.clientX, e.clientY);
        } else if (!target) {
             // If clicking outside a cell, deselect everything and hide the picker
             deselectAll();
             hideColorPicker();
        }
    });

    // 2. Context Menu (Right-click for advanced options like color)
    grid.addEventListener('contextmenu', function(e) {
        e.preventDefault(); // Prevent default browser context menu
        let target = e.target.closest('.cell');
        if (target) {
            selectCell(target);
            showColorPicker(target, e.clientX, e.clientY);
        } else {
             deselectAll();
             hideColorPicker();
        }
    });

    // 3. Keyup for contenteditable cells (Optional: handle basic input)
    grid.addEventListener('keyup', function(e) {
        if (e.target.classList.contains('cell')) {
            // Basic handling, no change needed unless specific validation is required
        }
