function showColorPicker(cellElement, x, y) {
    let picker = document.querySelector('.color-picker');
    if (!picker) {
        picker = document.createElement('div');
        picker.className = 'color-picker';
        document.body.appendChild(picker);
    }

    // Set position relative to the cell/cursor location
    picker.style.left = `${x + 10}px`;
    picker.style.top = `${y - 20}px`;
    picker.style.display = 'flex';

    // Populate controls
    picker.innerHTML = `
        <label for="color-input">Color:</label>
        <input type="color" id="color-input" value="#ffffff">
        <button id="apply-color-btn">Apply</button>
    `;

    const colorInput = document.getElementById('color-input');
    const applyButton = document.getElementById('apply-color-btn');

    // Set initial color based on current cell background (if any)
    colorInput.value = getComputedStyle(cellElement).backgroundColor || '#ffffff';


    // Event listener for applying the color
    applyButton.onclick = () => {
        const selectedColor = colorInput.value;
        applyBackgroundColor(cellElement, selectedColor);
        hideColorPicker(); // Hide after application
    };

    // Optional: Allow pressing Enter on input to apply
    colorInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
            applyButton.click();
        }
    });
}
