```javascript
function initializeSpreadsheet() {
    const grid = document.getElementById('spreadsheet-grid');
    const numRows = 20;
    const numCols = 10; // A to J

    // Function to generate column letters (A, B, C...)
    const getColLabel = (index) => String.fromCharCode(65 + index);

    for (let r = 2; r <= numRows; r++) {
        const rowContainer = document.createElement('div');
        rowContainer.className = 'row-container';
        rowContainer.setAttribute('data-row', r);

        // Row Label
        const rowLabel = document.createElement('div');
        rowLabel.className = 'row-label';
        rowLabel.setAttribute('data-row', r);
        rowLabel.textContent = r;
        rowContainer.appendChild(rowLabel);

        // Cells A to J
        for (let c = 0; c < numCols; c++) {
            const colLetter = getColLabel(c);
            const cell = document.createElement('div');
            cell.className = 'cell';
            cell.setAttribute('data-col', colLetter);
            cell.setAttribute('data-row', r);
            cell.contentEditable = true;
            cell.addEventListener('click', handleCellClick);
            rowContainer.appendChild(cell);
        }
        grid.appendChild(rowContainer);
    }

    // Add event listener for the color picker button
    document.getElementById('color-picker-btn').addEventListener('click', () => {
        showColorPicker();
    });
}
