function initializeColorPicker() {
    const container = document.querySelector('.spreadsheet-container');
    if (!container) return;

    // 1. Create the Color Picker Control (A simple input type="color")
    const colorControlWrapper = document.createElement('div');
    colorControlWrapper.className = 'color-picker-control';

    const colorInput = document.createElement('input');
    colorInput.type = 'color';
    colorInput.id = 'cellColorPicker';
    colorInput.value = '#ffffff'; // Default white background

    // 2. Add event listener to apply color when changed
    colorInput.addEventListener('change', (e) => {
        const selectedCell = document.querySelector('.cell.selected');
        if (selectedCell) {
            selectedCell.style.backgroundColor = e.target.value;
            // Optional: Update a data attribute if needed for persistence
            selectedCell.dataset.bgColor = e.target.value; 
        } else {
            console.warn("No cell selected to apply color.");
        }
    });

    colorControlWrapper.appendChild(document.createTextNode('Fondo: '));
    colorControlWrapper.appendChild(colorInput);

    // Insert the control right after the header row, but before the main grid content starts.
    const header = document.querySelector('.header');
    if (header) {
        header.parentNode.insertBefore(colorControlWrapper, document.getElementById('spreadsheet-grid'));
    }
}

// Call this function when the DOM is fully loaded
document.addEventListener('DOMContentLoaded', initializeColorPicker);
