### FUNCION: initializeSpreadsheet
```javascript
function initializeSpreadsheet() {
    const grid = document.getElementById('spreadsheet-grid');
    const rowLabelsContainer = document.querySelector('.row-label'); // Assuming this is used for the first row label

    // Function to generate a column letter (A, B, C...)
    function getColLetter(index) {
        let letter = '';
        while (index >= 0) {
            letter = String.fromCharCode((index % 26) + 65) + letter;
            Math.floor(index / 26)--;
            index = Math.floor(index / 26);
        }
        return letter;
    }

    // Function to generate a row number (1, 2, 3...)
    function getRowNumber(index) {
        return index + 1;
    }

    const numRows = 20;
    const numCols = 10; // A through J

    // Clear existing content if running multiple times
    grid.innerHTML = '';

    for (let r = 1; r <= numRows; r++) {
        const rowContainer = document.createElement('div');
        rowContainer.className = 'row-container';
        rowContainer.setAttribute('data-row', r);

        // Row Label
        const rowLabel = document.createElement('div');
        rowLabel.className = 'row-label';
        rowLabel.setAttribute('data-row', r);
        rowLabel.textContent = r;
        rowContainer.appendChild(rowLabel);

        // Cells A to J
        for (let c = 0; c < numCols; c++) {
            const colLetter = getColLetter(c);
            const cell = document.createElement('div');
            cell.className = 'cell';
            cell.setAttribute('data-col', colLetter);
            cell.setAttribute('data-row', r);
            cell.contentEditable = 'true';
            // Add basic event listeners for content editing/selection
            cell.addEventListener('input', handleCellInput);
            cell.addEventListener('click', handleCellClick);
            rowContainer.appendChild(cell);
        }

        grid.appendChild(rowContainer);
    }

    // Attach column label click handlers after generation
    document.querySelectorAll('.col-label').forEach(label => {
        label.addEventListener('click', handleColumnLabelClick);
    });

    // Initialize event listeners for all cells (for contenteditable)
    document.querySelectorAll('.cell').forEach(cell => {
        cell.addEventListener('focus', handleCellFocus);
        cell.addEventListener('blur', handleCellBlur);
    });
}
