```javascript
function deleteColumn(colName) {
    if (!confirm(`¿Está seguro de que desea eliminar la columna ${colName}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Visually hide all cells in the column
    document.querySelectorAll(`.cell[data-col="${colName}"]`).forEach(cell => {
        cell.classList.add('hidden');
        cell.setAttribute('contenteditable', 'false'); // Disable editing
        cell.innerHTML = ''; // Clear content immediately
    });

    // 2. Remove the column label visually (optional, but good practice)
    const colLabel = document.querySelector(`.col-label[data-col="${colName}"]`);
    if (colLabel) {
        colLabel.classList.add('hidden');
    }
}
