function setBackgroundColorColumn(colName, color) {
    // 1. Remove existing custom background classes/styles first
    document.querySelectorAll('.custom-bg').forEach(el => {
        el.classList.remove('custom-bg');
        el.style.setProperty('--user-bg-color', '');
        el.style.setProperty('--user-border-color', '');
