function handleColumnSelect(event) {
    const selectedLabel = event.currentTarget;
    const colName = selectedLabel.dataset.col;

    // 1. Deselect previous column and controls
    document.querySelectorAll('.col-label').forEach(label => label.classList.remove('selected'));
    document.getElementById('column-controls').classList.add('hidden');

    // 2. Select current column
    selectedLabel.classList.add('selected');

    // 3. Show and populate controls panel
    const controlPanel = document.getElementById('column-controls');
    controlPanel.innerHTML = `
        <button id="delete-col-btn" class="action-btn">🗑️ Borrar Columna</button>
        <div style="margin: 10px 0;">
            <label for="color-picker">Color de Fondo:</label>
            <input type="color" id="color-picker" value="#ff0000">
            <button id="apply-color-btn" class="action-btn">🎨 Aplicar Color</button>
        </div>
        <button id="clear-col-content-btn" class="action-btn">🧹 Vaciar Contenido Columna</button>
    `;
    controlPanel.classList.remove('hidden');

    // 4. Attach listeners to new controls
    document.getElementById('delete-col-btn').addEventListener('click', () => deleteColumn(colName));
    document.getElementById('apply-color-btn').addEventListener('click', () => changeBackgroundColor(colName, document.getElementById('color-picker').value));
    document.getElementById('clear-col-content-btn').addEventListener('click', () => clearColumnContent(colName));
}
