/**
 * Handles column selection logic and displays controls panel.
 * @param {Event} event - The click event object.
 */
function handleColumnSelect(event) {
    const selectedLabel = event.currentTarget;
    const colName = selectedLabel.dataset.col;

    // 1. Deselect previous column and controls
    document.querySelectorAll('.col-label').forEach(label => label.classList.remove('selected'));
    document.getElementById('column-controls').classList.add('hidden');

    // 2. Select current column
    selectedLabel.classList.add('selected');

    // 3. Show and populate controls panel
    const controlPanel = document.getElementById('column-controls');
    controlPanel.innerHTML = `
        <button id="delete-col-btn" class="action-btn">🗑️ Borrar Columna</button>
        <div style="margin: 10px 0;">
            <label for="color-picker" style="font-weight: bold; margin-right: 5px;">Color de Fondo:</label>
            <input type="color" id="color-picker" value="#ff0000">
            <button id="apply-color-btn" class="action-btn">🎨 Aplicar Color</button>
        </div>
        <button id="clear-col-content-btn" class="action-btn">🧹 Vaciar Contenido Columna</button>
    `;
    controlPanel.classList.remove('hidden');

    // 4. Attach listeners to new controls
    document.getElementById('delete-col-btn').addEventListener('click', () => deleteColumn(colName));
    document.getElementById('apply-color-btn').addEventListener('click', () => changeBackgroundColor(colName, document.getElementById('color-picker').value));
    document.getElementById('clear-col-content-btn').addEventListener('click', () => clearColumnContent(colName));
}

/**
 * Deletes all cells belonging to the specified column from the DOM.
 * @param {string} colName - The data attribute value of the column (e.g., 'A').
 */
function deleteColumn(colName) {
    if (!confirm(`¿Estás seguro de que deseas borrar la columna ${colName}? Esta acción es irreversible.`)) return;

    const cells = document.querySelectorAll(`.cell[data-col="${colName}"]`);
    cells.forEach(cell => cell.remove());
}

/**
 * Changes the background color of all cells in the specified column.
 * @param {string} colName - The data attribute value of the column.
 * @param {string} color - The hex color code to apply.
 */
function changeBackgroundColor(colName, color) {
    const cells = document.querySelectorAll(`.cell[data-col="${colName}"]`);
    cells.forEach(cell => {
        // Reset existing background styles/classes first
        cell.style.backgroundColor = ''; 
        cell.classList.remove('custom-bg');

        // Apply new color and class
        cell.style.backgroundColor = color;
        cell.classList.add('custom-bg');
    });
}

/**
 * Clears the content of all cells in the specified column.
 * @param {string} colName - The data attribute value of the column.
 */
function clearColumnContent(colName) {
    const cells = document.querySelectorAll(`.cell[data-col="${colName}"]`);
    cells.forEach(cell => {
        // Clear content by setting innerHTML/textContent to empty string
        cell.innerHTML = ''; 
        cell.textContent = '';
    });
}

/**
 * Sets up the event listeners for column selection controls when the DOM is ready.
 */
function setupColumnSelectionControls() {
    const colLabels = document.querySelectorAll('.col-label');
    const controlPanel = document.getElementById('column-controls');

    // Clear previous listeners and state (important if this function were called multiple times)
    colLabels.forEach(label => label.removeEventListener('click', handleColumnSelect));
    controlPanel.innerHTML = '';
    controlPanel.classList.add('hidden');

    // Attach new listener to all column labels
    colLabels.forEach(label => {
        label.addEventListener('click', handleColumnSelect);
    });
}
