function handleContextMenu(e) {
    e.preventDefault(); // Prevent default browser context menu

    const target = e.target;
    let colLetter = null;

    // Determine if the click happened on a column label (A, B, C...)
    if (target.classList.contains('col-label')) {
        colLetter = target.getAttribute('data-col');
    } else if (target.closest('.cell') && target.closest('.cell').hasAttribute('data-col')) {
        // If clicking inside a cell, use the cell's column data
        const cell = target.closest('.cell');
        colLetter = cell.getAttribute('data-col');
    }

    if (colLetter) {
        selectColumn(colLetter);
        showContextMenu(e.clientX, e.clientY);
    } else {
        // If not clicking on a column/cell header, hide the menu
        hideContextMenu();
    }
}
