```javascript
function toggleColumnVisibility(event) {
    const colLabel = event.currentTarget;
    const colLetter = colLabel.dataset.col;
    if (!colLetter) return;

    // 1. Determinar si está oculto o visible
    let isHidden = colLabel.classList.contains('hidden');

    // 2. Seleccionar todos los elementos de celda de esta columna
    const cells = document.querySelectorAll(`.cell[data-col="${colLetter}"]`);

    if (isHidden) {
        // Mostrar columna: resetear display y remover clase hidden
        cells.forEach(cell => cell.style.display = '');
        colLabel.classList.remove('hidden');
    } else {
        // Ocultar columna: establecer display none y añadir clase hidden
        cells.forEach(cell => cell.style.display = 'none');
        colLabel.classList.add('hidden');
    }

    // 3. Actualizar la selección si es necesario (opcional, pero bueno para UX)
    // Si ocultamos una columna, debemos deseleccionar cualquier celda que esté en ella.
    if (!isHidden) {
        document.querySelectorAll('.cell[data-col="${colLetter}"]').forEach(cell => cell.classList.remove('selected'));
    }
}
