function handleCellInput(event) {
    const cell = event.target;
    const row = cell.dataset.row;
    const col = cell.dataset.col;
    if (!row || !col) return;

    // 1. Guardar el contenido en localStorage
    const key = `data_${row}_${col}`;
    localStorage.setItem(key, cell.textContent);

    // 2. Actualizar la selección y los controles si es necesario (ej: al hacer blur)
    if (event.type === 'blur') {
        selectRow({ currentTarget: cell.closest('.cell') }); // Simular evento de selección para actualizar el estado
    }
}
