    document.querySelectorAll('.row-label').forEach(label => {
        label.addEventListener('click', selectRow);
    });

    // Listener global para guardar contenido en localStorage cuando se edita una celda
    const grid = document.getElementById('spreadsheet-grid');
    if (grid) {
        grid.addEventListener('input', function(e) {
            if (e.target.classList.contains('cell')) {
                const cell = e.target;
                const row = cell.dataset.row;
                const col = cell.dataset.col;
                // Guardamos el texto sin espacios en blanco al inicio o final
                const content = cell.textContent.trim(); 

                // Clave: "cell_fila_columna" (ej: "2_B")
                localStorage.setItem(`cell_${row}_${col}`, content);
            }
        });
    }
}

function loadData() {
    const grid = document.getElementById('spreadsheet-grid');
    if (!grid) return;

    // Iterar sobre todos los elementos de celda para cargar datos desde localStorage
    document.querySelectorAll('.cell').forEach(cell => {
        const row = cell.dataset.row;
        const col = cell.dataset.col;
        const key = `cell_${row}_${col}`;
        const savedContent = localStorage.getItem(key);

        if (savedContent !== null) {
            // Restaurar el contenido de la celda
            cell.textContent = savedContent;
        } else {
             // Asegurarse de que las celdas sin datos cargados estén vacías
             cell.textContent = ''; 
        }
    });
}

// Inicialización: Cargar datos y luego configurar listeners
document.addEventListener('DOMContentLoaded', () => {
    loadData();
    initializeColumnListeners();
});
