### FUNCION: handleCellInput
```js
function handleCellInput(e) {
    const cell = e.target;
    let content = cell.textContent.trim();

    // 1. Si el contenido es un número o está vacío, no hacemos nada especial (o lo limpiamos si era fórmula).
    if (!isNaN(parseFloat(content)) || content === '') {
        return;
    }

    // 2. Detectar y evaluar fórmulas
    const formulaMatch = content.toUpperCase().match(/^=SUMA\((.*)\)/);
    if (formulaMatch) {
        let sum = 0;
        const argsString = formulaMatch[1]; // e.g., "A1;B1"
        const cellReferences = argsString.split(';').map(ref => ref.trim());

        for (const ref of cellReferences) {
            // Intentar encontrar el elemento de la celda referenciada en el DOM
            const targetCell = document.querySelector(`.cell[data-col="${getColFromRef(ref)}"][data-row="${getRowFromRef(ref)}"]`);
            if (targetCell && targetCell.textContent.trim() !== '') {
                // Asumimos que los valores referenciados son numéricos para la suma
                const value = parseFloat(targetCell.textContent);
                if (!isNaN(value)) {
                    sum += value;
                }
            }
        }

        // Mostrar el resultado en lugar de la fórmula
        cell.textContent = sum;
    } else if (content.startsWith('=')) {
        // Si es una fórmula no soportada, simplemente dejamos que el usuario vea el texto por ahora.
    }
}

function getColFromRef(ref) {
    const colMatch = ref.match(/([A-Z]+)/);
    return colMatch ? colMatch[1] : null;
}

function getRowFromRef(ref) {
    const rowMatch = ref.match(/(\d+)/);
    return rowMatch ? rowMatch[1] : null;
}
