### FUNCION: calculateAndDisplayFormula
```javascript
function calculateAndDisplayFormula(event) {
    const cell = event.target;
    let value = cell.textContent.trim();

    if (!value || !value.startsWith('=')) {
        // Si no es una fórmula o está vacío, simplemente dejamos el valor actual (texto/número).
        return;
    }

    try {
        const formulaString = value.substring(1); // Quitar '='
        let result = null;

        // Implementación específica para SUMA(A1;B1) basado en la prueba fallida
        if (formulaString.toUpperCase().startsWith('SUMA')) {
            const match = formulaString.match(/SUMA\((.*)\)/i);
            if (!match) return;

            const argsString = match[1]; 
            // Los argumentos están separados por punto y coma (;)
            const cellReferences = argsString.split(';').map(s => s.trim());

            let sum = 0;
            for (const ref of cellReferences) {
                if (!ref) continue;

                // Extraer columna y fila de la referencia (ej: A1 -> Col=A, Row=1)
                const colMatch = ref.match(/([A-Z]+)/i);
                const rowMatch = ref.match(/(\d+)/);

                if (colMatch && rowMatch) {
                    const colChar = colMatch[0].toUpperCase();
                    const rowNum = parseInt(rowMatch[1]);

                    // Buscar el elemento de celda real en el DOM
                    const targetCell = document.querySelector(`.cell[data-col="${colChar}"][data-row="${rowNum}"]`);

                    if (targetCell) {
                        let value;
                        // Intentar parsear el contenido del objetivo como número
                        value = parseFloat(targetCell.textContent); 
                        if (isNaN(value)) {
                            value = 0; // Tratar no números como cero para la suma
                        }
                        sum += value;
                    } else {
                        console.warn(`Referencia de celda ${ref} no encontrada.`);
                        return; // Si falta una referencia, fallamos el cálculo
                    }
                } else {
                    console.error(`Formato de referencia inválido: ${ref}`);
                    return; 
                }
            }
            result = sum.toString();
        }

        if (result !== null) {
            // Mostrar solo el resultado calculado en la celda
            cell.textContent = result;
        } else {
             // Si es una fórmula que no podemos calcular, dejarlo como texto para el usuario
             // Pero dado el requisito de mostrar el resultado, si falla, lo dejamos con su valor actual (el texto de la fórmula).
        }

    } catch (e) {
        console.error("Error al procesar la fórmula:", e);
        // En caso de error, no cambiamos el contenido para que el usuario vea qué falló.
    }
}
