### FUNCION: handleCellInput
```js
function handleCellInput(event) {
    const cell = event.target;
    let value = cell.textContent.trim();

    // 1. Verificar si el contenido es una fórmula
    if (!value || !value.startsWith('=')) {
        return false; // No es una fórmula, no hacer nada
    }

    // Eliminar '=' para procesar la expresión
    let expression = value.substring(1).trim(); 

    // Regex simple que asume el formato: =REF1 OP REF2 (ej: A1-B1)
    const match = expression.match(/^([A-Z]+[0-9]+)([+\-*/])([A-Z]+[0-9]+)$/);

    if (!match) {
        // Si el formato no coincide, dejamos que el usuario edite libremente (o lo limpiamos si es inválido)
        return false; 
    }

    let ref1 = match[1];
    let operator = match[2];
    let ref2 = match[3];

    // Función auxiliar para obtener el elemento de la celda referenciada en el DOM
    const getCellElement = (ref) => {
        const colMatch = ref.match(/[A-Z]+/);
        const rowMatch = ref.match(/[0-9]+/);
        if (!colMatch || !rowMatch) return null;

        const col = colMatch[0];
        const row = rowMatch[0];
        // Buscamos el elemento .cell con los data attributes correctos
        return document.querySelector(`.cell[data-col="${col}"][data-row="${row}"]`);
    };

    const cell1Element = getCellElement(ref1);
    const cell2Element = getCellElement(ref2);

    if (!cell1Element || !cell2Element) {
        // Si las celdas referenciadas no existen, no calculamos nada.
        return false; 
    }

    // Obtener valores numéricos de las celdas referenciadas
    let val1 = parseFloat(cell1Element.textContent);
    let val2 = parseFloat(cell2Element.textContent);

    if (isNaN(val1) || isNaN(val2)) {
        return false; // No se pueden calcular los valores
    }

    let result;
    switch (operator) {
        case '+':
            result = val1 + val2;
            break;
        case '-':
            result = val1 - val2;
            break;
        case '*':
            result = val1 * val2;
            break;
        case '/':
            if (val2 === 0) {
                cell.textContent = "Error: Div/0";
                return true; // Se actualizó el contenido, aunque sea un error
            }
            result = val1 / val2;
            break;
    }

    // Actualizar el contenido de la celda con el resultado calculado
    // Usamos textContent para asegurar que se muestre solo el valor numérico.
    cell.textContent = result;
    return true;
}
