### FUNCION: calculateFormula
```js
function calculateFormula(event) {
    const cell = event.target;
    let value = cell.value.trim();

    if (!value || !value.startsWith('=')) {
        // Si no es una fórmula, simplemente dejamos el valor tal cual (o lo limpiamos si se borra)
        return;
    }

    // 1. Extraer la fórmula sin el signo '='
    let formula = value.substring(1).trim();

    try {
        // 2. Reemplazar referencias de celda (A1, B1, etc.) con sus valores numéricos reales.
        // Esta es una simplificación: asumimos que las referencias son válidas y están en el DOM.
        let evaluatedFormula = formula;
        const cells = document.querySelectorAll('.row-container .cell');

        // Mapear cada celda a su referencia (A1, B1...)
        cells.forEach((cellElement, index) => {
            // Determinar la columna y fila de esta celda para crear una clave como 'A1'
            const colIndex = Array.from(cellElement.parentNode.children).indexOf(cellElement);
            const rowData = cellElement.closest('.row-container').dataset.row;

            if (rowData && colIndex >= 0) {
                // Generar la referencia de celda (A, B, C...) y el número de fila
                const columnLabel = document.querySelector(`.col-label[data-col="${String.fromCharCode(65 + colIndex)}"]`);
                let cellReference;
                if (columnLabel) {
                    cellReference = `${columnLabel.dataset.col}${rowData}`;
                } else {
                    // Fallback si no se encuentra el label de columna, aunque debería existir en la estructura
                    cellReference = String.fromCharCode(65 + colIndex) + rowData;
                }

                const cellValue = parseFloat(cellElement.textContent) || 0;

                // Reemplazar todas las ocurrencias de esta referencia con el valor numérico
                // Usamos una expresión regular global para reemplazar todas las instancias
                const regex = new RegExp('\\b' + cellReference + '\\b', 'g');
                evaluatedFormula = evaluatedFormula.replace(regex, cellValue);
            }
        });

        // 3. Evaluar la fórmula matemática resultante (ej: "4-2")
        // Usamos eval() con precaución, pero es necesario para este tipo de funcionalidad en un entorno sin librería math.js.
        const result = eval(evaluatedFormula);

        if (isNaN(result) || !isFinite(result)) {
            cell.value = 'Error'; // Mostrar error si la fórmula no se puede resolver
            return;
        }

        // 4. Actualizar el contenido de la celda con el resultado y limpiar el valor de la fórmula
        cell.textContent = result;
        cell.value = result; // Mantener el valor numérico en el input para futuras referencias

    } catch (e) {
        console.error("Error al calcular la fórmula:", e);
        cell.textContent = 'Error';
        cell.value = '';
    }
}
