### FUNCION: calculateFormula
```js
function calculateFormula(formulaString, currentCell) {
    // Regex para encontrar referencias de celda (ej: A1, J10)
    const cellRefRegex = /([A-Z]+[1-9]\d*)/g; 

    let processedFormula = formulaString;

    // Reemplazar todas las referencias de celda con sus valores numéricos actuales
    processedFormula = processedFormula.replace(cellRefRegex, (match) => {
        const [colChar, rowNumStr] = match.toUpperCase().match(/([A-Z]+)([1-9]\d*)/);
        if (!colChar || !rowNumStr) return match;

        // Buscar el elemento de celda correspondiente en el DOM
        const targetCell = document.querySelector(`.cell[data-col="${colChar}"][data-row="${rowNumStr}"]`);

        if (targetCell && targetCell.textContent !== '') {
            let value = targetCell.textContent;
            // Intentar convertir a número flotante para la evaluación
            const numericValue = parseFloat(value);
            if (!isNaN(numericValue)) {
                return numericValue; // Devolver el valor numérico directamente
            }
        }
        // Si no se encuentra o no es un número válido, devolver 0 (o dejarlo como referencia si fuera necesario)
        return '0'; 
    });

    try {
        // Evaluar la cadena matemática resultante. Esto requiere que los valores reemplazados sean números.
        const result = eval(processedFormula);
        if (isNaN(result)) return ''; // Retornar vacío si el resultado es NaN
        return result.toString();
    } catch (e) {
        console.error("Error de evaluación:", e);
        return 'ERROR'; 
    }
}
