function clearColumnContent(columnName) {
    // Selecciona todas las celdas de la columna dada y vacía su contenido.
    const cells = document.querySelectorAll(`.cell[data-col="${columnName}"]`);
    cells.forEach(cell => {
        cell.textContent = '';
        cell.innerHTML = '';
    });
}
