    document.querySelectorAll('.row-label').forEach(label => {
        label.addEventListener('click', selectRow);
    });

    // Añadir listener global para manejar la tecla DELETE en cualquier celda editable
    const cells = document.querySelectorAll('.cell[contenteditable="true"]');
    cells.forEach(cell => {
        cell.addEventListener('keydown', function(e) {
            if (e.key === 'Delete' || e.key === 'Backspace') {
                // Si se detecta la tecla de borrado, asumimos que el usuario quiere borrar toda la columna asociada a esta celda.
                e.preventDefault(); 

                const colName = this.dataset.col;
                if (colName) {
                    clearColumnContent(colName);
                }
            }
        });
    });
}
